const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{webcrypto}=require('node:crypto');
const {JSDOM,ResourceLoader,VirtualConsole}=require('jsdom');const C=require('../dist/core.js');const ROOT=path.resolve(__dirname,'../dist'),NOW=Date.parse('2026-10-21T22:00:00Z');const pause=n=>new Promise(r=>setTimeout(r,n));const clone=v=>JSON.parse(JSON.stringify(v??null));
function fixture(){const cfg={tables:JSON.parse(fs.readFileSync(ROOT+'/seed-tables.json')),servers:JSON.parse(fs.readFileSync(ROOT+'/seed-servers.json')),formations:JSON.parse(fs.readFileSync(ROOT+'/seed-formations.json'))};const live=C.initial(cfg,NOW);live.shifts.PM={formation:'test',rows:[{id:'aj',server:'A.J.',section:'2',cut:false,beeper:'',barAuto:true,entries:[]},{id:'bar',server:'Sarah Kibler',section:'BAR',cut:false,beeper:'',barAuto:true,entries:[]}],assignments:{B2:'aj',B3:'aj'}};const data={app:{config:cfg,live}},listeners=new Set(),commits=[];let version=0,delay=15;
 const read=parts=>clone(parts.reduce((v,k)=>v?.[k],data));const set=(parts,value)=>{let target=data;for(const p of parts.slice(0,-1))target=target[p]??={};if(value===null)delete target[parts.at(-1)];else target[parts.at(-1)]=clone(value);version++;for(const l of listeners){if(l.parts[0]==='.info')continue;const value=read(l.parts);if(l.event==='value')queueMicrotask(()=>l.fn(snapshot(value,l.parts.at(-1))));else for(const [key,v]of Object.entries(value||{}))if(!l.seen.has(key)){l.seen.add(key);queueMicrotask(()=>l.fn(snapshot(v,key)));}}};
 const snapshot=(value,key='')=>({key,val:()=>clone(value),exists:()=>value!=null});
 function ref(parts){return {child:p=>ref([...parts,...p.split('/')]),on(event,fn){const l={parts,event,fn,seen:new Set(),ready:false};listeners.add(l);const v=parts[0]==='.info'?parts[1]==='connected'?true:0:read(parts);if(event==='value')queueMicrotask(()=>{l.ready=true;fn(snapshot(v,parts.at(-1)));});else for(const [key,value]of Object.entries(v||{})){l.seen.add(key);queueMicrotask(()=>fn(snapshot(value,key)));}},off(event,fn){for(const l of listeners)if(l.fn===fn)listeners.delete(l);},onDisconnect:()=>({remove:async()=>{}}),get:async()=>snapshot(read(parts)),set:async v=>{set(parts,v);},remove:async()=>{set(parts,null);},update:async patch=>{for(const [key,value]of Object.entries(patch))set([...parts,...key.split('/')],value);},push:async value=>{const key='key_'+webcrypto.randomUUID();set([...parts,key],value);return ref([...parts,key]);},orderByKey(){return this;},limitToLast(){return this;},transaction:async(fn,cb,applyLocally)=>{assert.equal(applyLocally,false,'operations suppress unconfirmed local events');for(let attempts=0;attempts<30;attempts++){const complete=parts.length!==1||[...listeners].some(l=>l.event==='value'&&l.parts.join('/')===parts.join('/')&&l.ready);const v=version,value=fn(complete?read(parts):null);if(value===undefined)return {committed:false,snapshot:snapshot(read(parts))};await pause(delay);if(v!==version)continue;set(parts,value);commits.push({path:parts.join('/'),revision:value.revision});return {committed:true,snapshot:snapshot(value)};}throw Error('Fixture contention');}};}
 const db={ref:p=>ref(p.split('/'))},firebase={apps:[],initializeApp(){const app={name:'fz-host-next',database:()=>db};this.apps.push(app);return app;}};return {data,firebase,commits,setDelay:n=>delay=n};}
class Resources extends ResourceLoader{fetch(url){const u=new URL(url);if(u.origin!=='https://fzhost.test')throw Error('External QA traffic blocked');if(u.pathname.endsWith('firebase-app-compat.js'))return Promise.resolve(Buffer.from('window.firebase=window.__fixtureFirebase'));if(u.pathname.endsWith('firebase-database-compat.js'))return Promise.resolve(Buffer.from(''));return Promise.resolve(fs.readFileSync(ROOT+u.pathname));}}
async function waitFor(fn,label,ms=6000){const end=Date.now()+ms;while(Date.now()<end){if(fn())return;await pause(10);}throw Error('Timed out: '+label);}
async function page(shared=fixture()){const errors=[],vc=new VirtualConsole();vc.on('jsdomError',e=>{if(!/CSS stylesheet|navigation \(except/.test(e.message))errors.push(e.message);});const dom=new JSDOM(fs.readFileSync(ROOT+'/index.html','utf8'),{url:'https://fzhost.test/index.html',resources:new Resources(),runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(w){const RealDate=Date;w.Date=class extends RealDate{constructor(...args){super(...(args.length?args:[NOW]));}static now(){return NOW;}};Object.defineProperty(w,'crypto',{value:webcrypto});w.TextEncoder=TextEncoder;w.__fixtureFirebase=shared.firebase;if(shared.SpeechRecognition)w.SpeechRecognition=shared.SpeechRecognition;w.fetch=async()=>({ok:true,json:async()=>({databaseURL:'https://fixture.test',path:'app'})});w.confirm=()=>true;w.prompt=()=>null;w.HTMLElement.prototype.scrollIntoView=function(){};w.HTMLDialogElement.prototype.showModal=function(){this.setAttribute('open','');};w.HTMLDialogElement.prototype.close=function(){this.removeAttribute('open');};w.HTMLMediaElement.prototype.play=async()=>{};w.HTMLMediaElement.prototype.pause=()=>{};}});try{await waitFor(()=>dom.window.FZHostApp?.state&&dom.window.document.getElementById('connection').textContent==='LIVE','LIVE bootstrap',12000);}catch(error){const diagnostics=errors.join('; ')+' '+dom.window.document.getElementById('notice')?.textContent;dom.window.close();throw Error(error.message+' '+diagnostics);}return {w:dom.window,dom,shared,errors};}
async function seatUI(p){const w=p.w;w.document.querySelector('[data-table="B2"]').click();w.document.getElementById('seatPeople').value='6';w.document.getElementById('seatServer').value='aj';w.document.querySelector('[name=secondary][value="B3"]').checked=true;w.document.getElementById('seatForm').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await waitFor(()=>w.FZHostApp.state.tables.B2.status==='seated'&&!w.FZHostApp.connection.busy,'seat acknowledgement');}
test('actual DOM: seat B2/AJ + B3 secondary, delete highlighted B3, Undo restores Board + both tables',async()=>{const p=await page();try{await seatUI(p);const id=p.w.FZHostApp.state.tables.B2.partyId;assert.equal(p.w.FZHostApp.state.tables.B3.partyId,id);p.w.document.querySelector('[data-table="B3"]').click();p.w.document.getElementById('deleteAction').click();await waitFor(()=>p.w.FZHostApp.state.tables.B3.status==='ready'&&!p.w.FZHostApp.connection.busy,'Delete');assert.equal(p.w.FZHostApp.state.tables.B2.status,'ready');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].entries.length,0);assert(p.w.document.querySelector('[data-table="B3"]').classList.contains('selected'));p.w.document.getElementById('undoTableAction').click();await waitFor(()=>p.w.FZHostApp.state.tables.B3.status==='seated'&&!p.w.FZHostApp.connection.busy,'Undo');assert.equal(p.w.FZHostApp.state.tables.B2.partyId,id);assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].entries[0].id,id);assert.deepEqual(p.errors,[]);}finally{p.dom.window.close();}});
test('two real DOM clients receive the same committed state without polling or REST locks',async()=>{const shared=fixture(),a=await page(shared),b=await page(shared);try{await seatUI(a);await waitFor(()=>b.w.FZHostApp.state.tables.B3.status==='seated','second tablet realtime');assert.equal(b.w.FZHostApp.state.tables.B2.partyId,a.w.FZHostApp.state.tables.B2.partyId);assert.equal(shared.commits.filter(c=>c.path==='app/live').length,1);assert(!shared.commits.some(c=>c.path.includes('lock')));}finally{a.dom.window.close();b.dom.window.close();}});
test('SAVED is not shown while transaction acknowledgement is pending',async()=>{const p=await page();try{p.shared.setDelay(180);p.w.document.querySelector('[data-table="B2"]').click();p.w.document.getElementById('seatServer').value='aj';p.w.document.getElementById('seatForm').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));await pause(40);assert.equal(p.w.FZHostApp.state.tables.B2.status,'ready');assert.equal(p.w.document.getElementById('seatSubmit').disabled,true);await waitFor(()=>p.w.FZHostApp.state.tables.B2.status==='seated','confirmed seat');assert.equal(p.w.document.querySelector('[data-table="B2"]').classList.contains('seated'),true);}finally{p.dom.window.close();}});
test('all thirteen retained operations plus Undo are visible; no reports/analytics menu exists',async()=>{const p=await page();try{const labels=[...p.w.document.querySelectorAll('.op-card strong')].map(e=>e.textContent);for(const name of ['Formation & Servers','Breaking Section','Beeper','Edit Table Map','Edit Formation','Correct Wrong AM / PM','Cut / Uncut Employee','Reservations','Manager Chat / VN / Call','Team Shout Out','Edit Manager Password','Repair BAR · Auto SKIP','Clear Board + Shift AM','Clear Board + Shift PM','Undo Delete'])assert(labels.includes(name),name);assert(labels.includes('Beeper History'));assert(!labels.some(n=>/analytics|report/i.test(n)));assert.equal(p.w.document.querySelectorAll('.table').length,56);}finally{p.dom.window.close();}});

 test('UUID fallback works without randomUUID on older tablet contexts',()=>{const vm=require('node:vm'),context={crypto:{getRandomValues:a=>webcrypto.getRandomValues(a)}};vm.runInNewContext(fs.readFileSync(ROOT+'/core.js','utf8'),context);const ids=new Set(Array.from({length:100},()=>context.HostCore.uid()));assert.equal(ids.size,100);for(const id of ids)assert.match(id,/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/);});
test('classic seating wizard submits one atomic B2/AJ plus B3 party and keeps all 45 visible rotation cells',async()=>{const p=await page();try{const d=p.w.document;d.querySelector('[data-entry-role="Front Host"]').click();assert.equal(d.getElementById('roleGate').hidden,true);assert(d.getElementById('board').classList.contains('active'));assert.equal(d.querySelectorAll('.board-row:first-child .turn').length,45);d.querySelector('[data-row-seat="aj"]').click();d.querySelector('[data-pick-table="B2"]').click();d.getElementById('wizardNext').click();d.querySelector('[data-people="5"]').click();const secondary=d.querySelector('#wizardBody input[value="B3"]');secondary.checked=true;secondary.dispatchEvent(new p.w.Event('change',{bubbles:true}));d.getElementById('wizardNext').click();assert.equal(d.getElementById('wizardNext').textContent,'SUBMIT');assert(d.querySelector('[data-server="aj"]').classList.contains('selected'));d.getElementById('wizardNext').click();await waitFor(()=>p.w.FZHostApp.state.tables.B2.status==='seated'&&!p.w.FZHostApp.connection.busy,'wizard save');assert.equal(p.w.FZHostApp.state.tables.B2.partyId,p.w.FZHostApp.state.tables.B3.partyId);assert.equal(p.w.FZHostApp.state.parties[p.w.FZHostApp.state.tables.B2.partyId].people,5);assert.equal(p.shared.commits.filter(c=>c.path==='app/live').length,1);assert.equal(d.getElementById('seatWizard').open,false);assert.equal(d.querySelectorAll('.board-row:first-child .turn').length,45);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});
test('classic bottom navigation and Floor modal preserve actions without database writes',async()=>{const p=await page();try{const d=p.w.document;assert.deepEqual([...d.querySelectorAll('nav [data-pane]')].map(b=>b.textContent),['BOARD','FLOOR','MESSAGE','MORE','WAITING LIST']);d.querySelector('[data-entry-role="Front Host"]').click();d.querySelector('[data-pane="floor"]').click();d.querySelector('[data-table="B2"]').click();assert.equal(d.getElementById('tableDialog').open,false);assert.equal(d.getElementById('wizardTitle').textContent,'Choose People');assert(d.querySelector('#seatWizard #wizardMarkReserved'));assert.equal(d.querySelector('#seatWizard [data-op=reservations]'),null);assert(d.querySelector('#seatWizard [data-op=undo]'));d.getElementById('wizardBack').click();assert.equal(d.getElementById('seatWizard').open,true);assert(d.querySelector('[data-pick-table="B2"]').classList.contains('selected'));d.getElementById('wizardBack').click();assert.equal(d.getElementById('seatWizard').open,false);assert.equal(p.shared.commits.length,0);}finally{await pause(30);p.dom.window.close();}});
test('Front Host can delete wrong party, Undo it, and open reservations from both primary screens',async()=>{const p=await page();try{const d=p.w.document;d.querySelector('[data-entry-role="Front Host"]').click();await seatUI(p);d.querySelector('[data-table="B3"]').click();assert.equal(d.getElementById('role').value,'Front Host');assert.equal(d.getElementById('advancedActions').hidden,false);for(const id of ['readyAction','cleanAction','moveAction','resetBoardAction','peopleAction','deleteAction','secondaryAction'])assert(d.getElementById(id));d.getElementById('deleteAction').click();await waitFor(()=>p.w.FZHostApp.state.tables.B2.status==='ready'&&!p.w.FZHostApp.connection.busy,'host delete');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].entries.length,0);assert(!d.getElementById('managerPassword'));d.getElementById('undoTableAction').click();await waitFor(()=>p.w.FZHostApp.state.tables.B2.status==='seated'&&!p.w.FZHostApp.connection.busy,'host undo');for(const pane of ['board','floor']){d.querySelector('#'+pane+' [data-op="reservations"]').click();assert.equal(d.getElementById('modalTitle').textContent,'Reservations');assert(d.getElementById('upcomingReservations'));d.getElementById('modalClose').click();}}finally{await pause(30);p.dom.window.close();}});
test('PM BAR visible ON/OFF button preserves two-real-tables to one-auto-skip rule',async()=>{const p=await page();try{const d=p.w.document;await p.w.FZHostApp.send('SEAT',{table:'Bar 1',rowId:'bar',people:1,secondary:[]});await p.w.FZHostApp.send('SEAT',{table:'Bar 2',rowId:'bar',people:1,secondary:[]});const autos=()=>p.w.FZHostApp.state.shifts.PM.rows.find(r=>r.id==='bar').entries.filter(e=>e.kind==='auto').length;assert.equal(autos(),1);assert.equal(d.querySelector('[data-bar-toggle="bar"]').textContent,'AUTO SKIP ON');d.querySelector('[data-bar-toggle="bar"]').click();await waitFor(()=>!p.w.FZHostApp.connection.busy&&autos()===0,'BAR off');assert.equal(d.querySelector('[data-bar-toggle="bar"]').textContent,'AUTO SKIP OFF');d.querySelector('[data-bar-toggle="bar"]').click();await waitFor(()=>!p.w.FZHostApp.connection.busy&&autos()===1,'BAR on');assert.equal(d.querySelector('[data-bar-toggle="bar"]').textContent,'AUTO SKIP ON');assert.equal(p.w.FZHostApp.state.tables['Bar 1'].status,'seated');assert.equal(p.w.FZHostApp.state.tables['Bar 2'].status,'seated');}finally{await pause(30);p.dom.window.close();}});
test('Floor shows assigned section, server and beeper even for READY tables; breaking assignments updates labels',async()=>{const p=await page();try{const d=p.w.document;assert.equal(d.querySelector('[data-table="B2"] strong').textContent,'B2-2');assert.match(d.querySelector('[data-table="B2"]').getAttribute('aria-label'),/Section 2 · A.J./);assert.equal(d.querySelector('[data-section-label="2"] .section-server').textContent,'A.J.');await p.w.FZHostApp.send('BEEPER',{rowId:'aj',beeper:'12'});assert.equal(d.querySelector('[data-section-label="2"] .section-beeper').textContent,'BEEPER 12');await p.w.FZHostApp.send('JOIN',{server:'New Server',section:'2B',tables:['B2']});assert.equal(d.querySelector('[data-table="B2"] strong').textContent,'B2-2B');assert.equal(d.querySelector('[data-section-label="2B"] .section-server').textContent,'New Server');assert.equal(d.querySelector('[data-table="B3"] strong').textContent,'B3-2');}finally{await pause(30);p.dom.window.close();}});
test('MIN/MAX guides follow active rotation slot counts after seats and skips',async()=>{const p=await page();try{const d=p.w.document;await p.w.FZHostApp.send('SEAT',{table:'B2',rowId:'aj',people:5,secondary:[]});assert.equal(d.querySelector('.frontier-guide.min').dataset.turn,'1');assert.equal(d.querySelector('.frontier-guide.max').dataset.turn,'3');await p.w.FZHostApp.send('SKIP',{rowId:'bar'});assert.equal(d.querySelector('.frontier-guide.min').dataset.turn,'2');assert.equal(d.querySelector('.frontier-guide.max').dataset.turn,'3');}finally{await pause(30);p.dom.window.close();}});
