test('Upcoming reservations display and show an in-app reminder only once at one hour',async()=>{const shared=fixture();shared.data.app.reservations={test_reminder:{name:'Test Guest',date:'2026-10-21',time:'18:00',people:4},test_future:{name:'Future Guest',date:'2026-10-23',time:'19:00',people:11}};const p=await page(shared);try{const d=p.w.document;d.querySelector('[data-entry-role="Front Host"]').click();await waitFor(()=>d.querySelector('.reservation-flow-alert'),'one-hour reminder');assert.match(d.querySelector('.reservation-flow-alert').textContent,/Test Guest/);assert.equal(d.querySelectorAll('.reservation-flow-alert').length,1);p.w.FZHostApp.operation('reservations');assert([...d.querySelectorAll('#reservationList [data-res-field=name]')].some(input=>input.value==='Future Guest'));assert(d.getElementById('enableReservationAlerts'));d.querySelector('.reservation-flow-alert [data-ack]').click();assert.equal(d.querySelectorAll('.reservation-flow-alert').length,0);assert.equal(p.shared.commits.filter(c=>c.path==='app/live').length,0);}finally{await pause(30);p.dom.window.close();}});
