test('Floor labels adapt to phone, tablet and desktop canvas sizes while full table names stay accessible',async()=>{const p=await page();try{const d=p.w.document,map=d.getElementById('map');for(const [width,height]of [[312,300],[382,460],[640,250],[780,490],[1024,650],[1600,800]]){Object.defineProperty(map,'clientWidth',{configurable:true,value:width});Object.defineProperty(map,'clientHeight',{configurable:true,value:height});p.w.FZHostApp.pane('floor');p.w.dispatchEvent(new p.w.Event('resize'));assert.equal(d.querySelectorAll('#map .table').length,56);const b=d.querySelector('[data-table="B2"]');assert.match(b.getAttribute('aria-label'),/B2 ready · Section 2 · A.J./);for(const t of map.querySelectorAll('.table')){const font=parseFloat(t.style.getPropertyValue('--table-font'));assert(Number.isFinite(font)&&font>=5&&font<=28);assert(t.querySelector('strong').textContent.length>0);}const bar=d.querySelector('[data-table="Bar 12"] strong');assert.equal(bar.textContent,width<600?'12':'Bar12');} }finally{await pause(30);p.dom.window.close();}});

