test('Upcoming reservation table edits and saves its own date, then deletes the same row',async()=>{const shared=fixture();shared.data.app.config.formations.test={'2':['B2','B3'],'4':['L5','L6','A4']};shared.data.app.reservations={future:{name:'Future Guest',date:'2026-10-23',time:'19:00',people:11,phone:'555',note:'Test'}};const p=await page(shared);try{const d=p.w.document;p.w.FZHostApp.operation('reservations');await waitFor(()=>d.querySelector('[data-res-edit="future"]'),'reservation row');assert.equal(d.querySelectorAll('.reservation-table th').length,10);let row=d.querySelector('[data-res-row="future"]');assert(row.querySelector('[data-res-field="name"]').disabled);row.querySelector('[data-res-edit]').click();row.querySelector('[data-res-field="name"]').value='Updated Guest';row.querySelector('[data-res-field="people"]').value='12';row.querySelector('[data-res-save]').click();await waitFor(()=>shared.data.app.reservations.future.name==='Updated Guest','inline save');assert.equal(shared.data.app.reservations.future.date,'2026-10-23');assert.equal(shared.data.app.reservations.future.people,12);d.querySelector('[data-res-delete="future"]').click();await waitFor(()=>shared.data.app.reservations.future.status==='deleted','delete reservation');assert.equal(shared.data.app.reservations.future.phone,'555');assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('Reservations wide layout blocks both new and edited parties below six guests',async()=>{const shared=fixture();shared.data.app.config.formations.test={'2':['B2','B3'],'4':['L5','L6','A4']};shared.data.app.reservations={future:{name:'Guest',date:'2026-10-23',time:'19:00',people:11}};const p=await page(shared);try{const d=p.w.document;p.w.FZHostApp.operation('reservations');await waitFor(()=>d.querySelector('[data-res-edit="future"]'),'row');assert(d.getElementById('modal').classList.contains('reservations-dialog'));assert.equal(d.querySelectorAll('.reservation-form-grid input').length,6);d.getElementById('resName').value='New Guest';d.getElementById('resTime').value='18:00';const guests=d.getElementById('resPeople');guests.value='5';guests.dispatchEvent(new p.w.Event('input'));assert(d.getElementById('saveReservation').disabled);d.getElementById('reservationForm').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));await pause(30);assert.equal(Object.keys(shared.data.app.reservations).length,1);d.querySelector('[data-res-edit="future"]').click();const input=d.querySelector('[data-res-field=people]');input.value='5';input.dispatchEvent(new p.w.Event('input'));assert(d.querySelector('[data-res-save]').disabled);assert.equal(shared.data.app.reservations.future.people,11);guests.value='6';guests.dispatchEvent(new p.w.Event('input'));assert.equal(d.getElementById('saveReservation').disabled,false);d.getElementById('reservationForm').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));await waitFor(()=>Object.keys(shared.data.app.reservations).length===2,'six guest save');assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('Manager map editor moves tables by section and formation editor preserves occupied party identity',async()=>{const shared=fixture();shared.data.app.config.formations.small={1:['A1'],2:['B2','B3']};shared.data.app.config.formations.large={4:['A1','A2'],5:['B2','B3']};const p=await page(shared);try{const d=p.w.document;await seatUI(p);const partyId=p.w.FZHostApp.state.tables.B2.partyId;d.querySelector('[data-entry-role="Owner"]').click();d.getElementById('firstPassword').value='TestingOnly123';d.getElementById('firstPasswordConfirm').value='TestingOnly123';d.getElementById('firstPasswordForm').dispatchEvent(new p.w.Event('submit',{bubbles:true,cancelable:true}));await waitFor(()=>d.getElementById('role').value==='Owner','manager setup');p.w.FZHostApp.operation('map');assert.equal(d.getElementById('modalTitle').textContent,'Edit Table Map');d.getElementById('mapTemplate').value='small';d.getElementById('mapTemplate').dispatchEvent(new p.w.Event('change'));d.getElementById('mapSection').value='1';d.querySelector('[data-map-table="B2"]').click();d.getElementById('mapSection').value='';d.querySelector('[data-map-table="B3"]').click();d.getElementById('saveTemplate').click();await waitFor(()=>shared.data.app.config.formations.small['1'].includes('B2'),'map saved');assert.deepEqual(shared.data.app.config.formations.small['2'],[]);assert.equal(p.w.FZHostApp.state.tables.B2.partyId,partyId);p.w.FZHostApp.operation('formation');d.getElementById('changeFormation').value='large';d.getElementById('changeFormation').dispatchEvent(new p.w.Event('change'));d.querySelector('[data-change-section="4"]').value='A.J.';d.querySelector('[data-change-section="5"]').value='Sarah Kibler';d.getElementById('saveFormationChange').click();await waitFor(()=>p.w.FZHostApp.state.shifts.PM.formation==='large','formation saved');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].id,'aj');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].section,'4');assert.equal(p.w.FZHostApp.state.tables.B3.partyId,partyId);assert.equal(p.w.FZHostApp.state.parties[partyId].rowId,'aj');assert.equal(p.w.FZHostApp.state.shifts.PM.assignments.B2,'bar');assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('CUT removes the entire Board row on both devices; UNCUT restores the same rotation',async()=>{const shared=fixture(),a=await page(shared),b=await page(shared);try{await seatUI(a);const before=JSON.stringify(a.w.FZHostApp.state.shifts.PM.rows[0].entries),party=a.w.FZHostApp.state.tables.B2.partyId;await a.w.FZHostApp.send('CUT',{rowId:'aj',cut:true});await waitFor(()=>!b.w.document.querySelector('[data-row-seat="aj"]'),'remote cut hidden');for(const p of [a,b]){assert(!p.w.document.querySelector('[data-skip="aj"]'));assert.equal(p.w.document.querySelectorAll('.board-row').length,1);assert.equal(p.w.FZHostApp.state.tables.B2.partyId,party);}await a.w.FZHostApp.send('CUT',{rowId:'aj',cut:false});await waitFor(()=>b.w.document.querySelector('[data-row-seat="aj"]'),'remote uncut restored');assert.equal(JSON.stringify(a.w.FZHostApp.state.shifts.PM.rows[0].entries),before);assert.equal(b.w.document.querySelectorAll('.board-row').length,2);assert.deepEqual(a.errors,[]);assert.deepEqual(b.errors,[]);}finally{await pause(30);a.dom.window.close();b.dom.window.close();}});

test('Board displays sections in numeric order with BAR last without reassigning rotation',async()=>{const shared=fixture(),rows=shared.data.app.live.shifts.PM.rows;rows[0].section='10';rows[1].section='BAR';rows.push({id:'s1',server:'First',section:'1',cut:false,beeper:'',barAuto:true,entries:[]},{id:'s2',server:'Second',section:'2 / 3',cut:false,beeper:'',barAuto:true,entries:[]});const before=JSON.stringify(rows);const p=await page(shared);try{const d=p.w.document;assert.deepEqual([...d.querySelectorAll('.board-row .section-bubble')].map(x=>x.textContent),['S1','S2 / 3','S10','BAR']);assert.equal(JSON.stringify(p.w.FZHostApp.state.shifts.PM.rows),before);assert.equal(shared.commits.length,0);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('Formation saves each arriving employee beside the selector with other sections blank and shares late arrivals',async()=>{const shared=fixture();shared.data.app.live=C.initial(shared.data.app.config,NOW);const a=await page(shared),b=await page(shared);try{const d=a.w.document;a.w.FZHostApp.operation('setup');d.getElementById('setupFormation').value=Object.keys(shared.data.app.config.formations)[0];d.getElementById('setupFormation').dispatchEvent(new a.w.Event('change'));await waitFor(()=>!a.w.FZHostApp.connection.busy,'formation saved');assert(!d.getElementById('saveSetup'));const form=d.getElementById('setupFormation').value,select=d.querySelector('#sectionAssignments select'),section=select.dataset.section;select.value=select.options[1].value;const name=select.value;const button=select.parentElement.querySelector('[data-save-section]');assert(button);button.click();await waitFor(()=>b.w.FZHostApp.state.shifts.PM.rows.length===1,'first arrival');assert.equal(b.w.FZHostApp.state.shifts.PM.rows[0].server,name);assert.equal(d.getElementById('modal').open,true);const selects=[...d.querySelectorAll('#sectionAssignments [data-section]')];assert(selects.slice(1).every(s=>s.value===''));const late=selects[1];late.value=late.options[2].value;late.parentElement.querySelector('[data-save-section]').click();await waitFor(()=>b.w.FZHostApp.state.shifts.PM.rows.length===2,'late arrival');assert.equal(b.w.FZHostApp.state.shifts.PM.formation,form);assert.equal(select.value,name);assert.equal(b.w.FZHostApp.state.shifts.PM.rows[0].section,section);assert.deepEqual(a.errors,[]);assert.deepEqual(b.errors,[]);}finally{await pause(30);a.dom.window.close();b.dom.window.close();}});

test('Formation saves beeper and shift beside the employee selector and shows bold identity metadata on Board',async()=>{const shared=fixture();shared.data.app.live=C.initial(shared.data.app.config,NOW);const p=await page(shared);try{const d=p.w.document;p.w.FZHostApp.operation('setup');d.getElementById('setupFormation').value=Object.keys(shared.data.app.config.formations)[0];d.getElementById('setupFormation').dispatchEvent(new p.w.Event('change'));await waitFor(()=>!p.w.FZHostApp.connection.busy,'formation saved');const select=d.querySelector('#sectionAssignments [data-section]'),box=select.parentElement;select.value=select.options[1].value;box.querySelector('[data-arrival-beeper]').value='12';box.querySelector('[data-arrival-shift]').value='Double';box.querySelector('[data-save-section]').click();await waitFor(()=>p.w.FZHostApp.state.shifts.PM.rows.length===1&&!p.w.FZHostApp.connection.busy,'identity saved');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].beeper,'12');assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].workShift,'Double');assert.match(d.querySelector('.beeper-chip').textContent,/12/);assert.match(d.querySelector('.work-shift-chip').textContent,/Double/);assert(d.querySelector('.cut-rules'));assert.equal(p.shared.commits.filter(c=>c.path==='app/live').length,2);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('Nine servers plus BAR retain all ten Floor labels at tablet and desktop sizes',async()=>{const shared=fixture(),cfg=shared.data.app.config,formation='9 SERVER';shared.data.app.live=C.reduce(C.initial(cfg,NOW),{type:'SETUP',id:'nine_setup',at:NOW,day:C.dayAt(NOW),shift:'PM',formation,servers:Object.fromEntries(Object.keys(cfg.formations[formation]).map((section,i)=>[section,'Server '+(i+1)]))},cfg);const p=await page(shared);try{const d=p.w.document,map=d.getElementById('map');for(const [width,height]of [[1024,650],[1366,768],[1600,800]]){Object.defineProperty(map,'clientWidth',{configurable:true,value:width});Object.defineProperty(map,'clientHeight',{configurable:true,value:height});p.w.FZHostApp.pane('floor');p.w.dispatchEvent(new p.w.Event('resize'));const labels=[...d.querySelectorAll('#sectionLabels .section-marker,#sectionOverflow .section-marker')];assert.equal(labels.length,10);assert.equal(d.querySelectorAll('#sectionOverflow .section-marker').length,0);assert.equal(d.querySelectorAll('#sectionLabels .section-marker').length,10);assert.equal(d.getElementById('sectionLabels').parentElement,map);assert.equal(d.querySelectorAll('#map .section-marker').length,10);assert.equal(new Set(labels.map(x=>x.dataset.sectionLabel)).size,10);assert(d.getElementById('sectionLabels').classList.contains('dense'));for(const label of labels){assert(label.querySelector('.section-number').textContent);assert(label.querySelector('.section-server').textContent);assert(label.querySelector('.section-beeper').textContent);}}assert.equal(d.querySelectorAll('#map .table').length,56);assert.equal(shared.commits.length,0);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('Assigned reservations show blue only on the reserved operational day; occupied tables stay red',async()=>{const shared=fixture();shared.data.app.reservations={today:{name:'Guest',date:'2026-10-21',time:'18:00',people:6,table:'B2'},future:{name:'Future',date:'2026-10-23',time:'18:00',people:6,table:'B3'}};const p=await page(shared);try{const d=p.w.document;await waitFor(()=>d.querySelector('[data-table="B2"]').classList.contains('reserved'),'reserved floor');assert(!d.querySelector('[data-table="B3"]').classList.contains('reserved'));await seatUI(p);assert(d.querySelector('[data-table="B2"]').classList.contains('seated'));assert(!d.querySelector('[data-table="B2"]').classList.contains('reserved'));assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

