test('Angela A4 to A3 move releases A4 and keeps one party and the same rotation position',async()=>{const shared=fixture(),cfg=shared.data.app.config;shared.data.app.live.shifts.PM.rows[0].server='Angela';let live=shared.data.app.live;live=C.reduce(live,{type:'SEAT',id:'angela_seat',at:NOW,day:C.dayAt(NOW),shift:'PM',rowId:'aj',table:'A4',secondary:[],people:2},cfg);shared.data.app.live=live;const p=await page(shared);try{const d=p.w.document,before=p.w.FZHostApp.state.shifts.PM.rows[0].entries[0].id;d.querySelector('[data-table="A4"]').click();d.getElementById('moveAction').click();assert.equal(d.querySelectorAll('#modalBody [name=secondary]').length,0);d.getElementById('newPrimary').value='A3';d.getElementById('newPrimary').dispatchEvent(new p.w.Event('change'));assert.match(d.getElementById('movePreview').textContent,/A4 becomes READY/);d.getElementById('savePartyEdit').click();await waitFor(()=>p.w.FZHostApp.state.tables.A4.status==='ready'&&!p.w.FZHostApp.connection.busy,'A4 released');const state=p.w.FZHostApp.state;assert.equal(state.tables.A3.status,'seated');assert.equal(Object.keys(state.parties).length,1);assert.equal(state.shifts.PM.rows[0].server,'Angela');assert.equal(state.shifts.PM.rows[0].entries.length,1);assert.equal(state.shifts.PM.rows[0].entries[0].id,before);assert.equal(state.shifts.PM.rows[0].entries[0].primary,'A3');assert.equal(d.querySelector('[data-table="A4"]').classList.contains('ready'),true);assert.equal(d.querySelector('[data-table="A3"]').classList.contains('seated'),true);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

