test('Floor reuses staff label nodes and cached placement on unchanged resize and table state updates',async()=>{const p=await page();try{const d=p.w.document,map=d.getElementById('map');Object.defineProperty(map,'clientWidth',{configurable:true,value:1024});Object.defineProperty(map,'clientHeight',{configurable:true,value:650});p.w.FZHostApp.pane('floor');p.w.dispatchEvent(new p.w.Event('resize'));const label=d.querySelector('#sectionLabels .section-marker'),line=d.querySelector('#sectionLabels svg line');p.w.dispatchEvent(new p.w.Event('resize'));assert.equal(d.querySelector('#sectionLabels svg line'),line);await p.w.FZHostApp.send('SKIP',{rowId:'aj',count:1});assert.equal(d.querySelector('#sectionLabels .section-marker'),label);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('One confirmed SAVE does not rebuild identical Board and Floor twice; timings expose database wait',async()=>{const p=await page();try{const d=p.w.document;let deliveries=0;const original=p.w.FZHostApp.connection.onState;p.w.FZHostApp.connection.onState=s=>{deliveries++;original(s);};const first=d.querySelector('.board-row');await p.w.FZHostApp.send('SKIP',{rowId:'aj',count:1});assert.equal(deliveries,1);const row=d.querySelector('.board-row');assert.notEqual(row,first);const key=p.w.FZHostApp.connection.state.revision;p.w.FZHostApp.connection.adopt();assert.equal(deliveries,1);assert.equal(p.w.FZHostApp.connection.state.revision,key);assert.equal(d.querySelector('.board-row'),row);assert.match(d.getElementById('lastSaved').textContent,/DB .*UI .*tries 1/);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

test('SAVE still confirms and unlocks when tablet local storage writes and removal fail',async()=>{const p=await page();try{const proto=p.w.Storage.prototype;proto.setItem=function(){throw new p.w.DOMException('Quota exceeded','QuotaExceededError');};proto.removeItem=function(){throw new p.w.DOMException('Storage unavailable','SecurityError');};await seatUI(p);assert.equal(p.w.FZHostApp.connection.busy,false);await p.w.FZHostApp.send('SKIP',{rowId:'aj',count:1});assert.equal(p.w.FZHostApp.connection.busy,false);assert.equal(p.w.FZHostApp.state.shifts.PM.rows[0].entries.length,2);assert.equal(p.shared.commits.filter(c=>c.path==='app/live').length,2);assert.deepEqual(p.errors,[]);}finally{await pause(30);p.dom.window.close();}});

